package web

import "html/template"

var continuityTemplate = template.Must(template.New("continuity").Parse(`
{{if .Error}}<div class="gas-error-summary" role="alert"><strong>Request refused</strong><span>{{.Error}}</span></div>{{end}}
{{if .Intake}}
<section class="gas-panel crab-toolbar"><div><span class="gas-badge gas-badge--info">Intake</span><h2>First reports</h2><p>Fast capture before an incident exists. Phone camera and file evidence stay inside the hostile-byte boundary.</p></div><div><strong>{{.Intake.HumanID}}</strong><br><span class="gas-muted">{{.Intake.Role}}</span></div></section>
<div class="crab-dashboard-grid crab-dashboard-grid--two crab-section-gap">
  <section class="gas-panel"><h2>Capture first report</h2><form method="post" action="/intake" enctype="multipart/form-data" class="gas-form"><div class="gas-field"><label>Reporter</label><input name="reporter" autocomplete="name"></div><div class="gas-field"><label>Contact route</label><input name="contact_route" placeholder="Phone, email or callback route"></div><div class="gas-field"><label>Received at</label><input type="datetime-local" name="received_at"><span class="gas-help">Leave blank to use capture time.</span></div><div class="gas-field"><label>Time confidence</label><select name="time_confidence"><option value="trusted">Trusted</option><option value="drifting">Drifting</option><option value="untrusted">Untrusted</option></select></div><div class="gas-field"><label>Description</label><textarea name="description" required></textarea></div><div class="gas-field"><label>Affected assets/services</label><input name="affected"></div><div class="gas-field"><label>Immediate impact</label><textarea name="immediate_impact"></textarea></div><div class="gas-field"><label>Source channel</label><select name="source_channel" required><option value="phone">Phone</option><option value="email">Email</option><option value="monitoring">Monitoring</option><option value="chat">Chat</option><option value="in_person">In person</option><option value="other">Other</option></select></div><div class="gas-field"><label>Camera photo</label><input type="file" name="camera" accept="image/*" capture="environment"></div><div class="gas-field"><label>Other evidence</label><input type="file" name="attachment" multiple></div><div><button class="gas-button gas-button--primary">Record first report</button></div></form></section>
  <section class="gas-panel"><h2>Intake rule</h2><p>Capture what is known. Do not force an incident declaration before there is enough information.</p><p>Association, retention or rejection is recorded separately so the original report remains immutable.</p></section>
</div>
<section class="gas-panel crab-section-gap"><h2>Report queue</h2>{{range .Intake.Reports}}<div class="crab-record"><strong>{{.Description}}</strong><span class="gas-muted">{{.ReportID}} · {{.SourceChannel}} · received {{.ReceivedAt}} · {{.AttachmentCount}} attachment(s)</span>{{if .Reporter}}<span>Reporter: {{.Reporter}}{{if .ContactRoute}} · {{.ContactRoute}}{{end}}</span>{{end}}{{if .Affected}}<span>Affected: {{.Affected}}</span>{{end}}{{if .ImmediateImpact}}<span>Impact: {{.ImmediateImpact}}</span>{{end}}{{if .Decision}}<span><strong>Disposition:</strong> {{.Decision}}{{if .IncidentID}} · {{.IncidentID}}{{end}} — {{.Reason}}</span>{{else if $.Intake.CanTriage}}<form method="post" action="/intake/{{.ReportID}}/triage" class="gas-form"><div class="gas-field"><label>Disposition</label><select name="decision"><option value="associate">Associate to incident</option><option value="retain">Retain for review</option><option value="reject">Reject as non-incident</option></select></div><div class="gas-field"><label>Incident ID</label><input name="incident_id" placeholder="Required when associating"></div><div class="gas-field"><label>Reason</label><textarea name="reason" required></textarea></div><div><button class="gas-button gas-button--primary">Record disposition</button></div></form>{{else}}<span class="gas-muted">Major triage required.</span>{{end}}</div>{{else}}<div class="gas-empty">No first reports captured.</div>{{end}}</section>
{{else if .Incident}}
<section class="gas-panel crab-operating-context"><div class="crab-toolbar"><div><div class="gas-cluster"><span class="gas-badge{{if eq .Incident.Mode "exercise"}} gas-badge--warning{{end}}">{{.Incident.Mode}}</span><span class="gas-badge gas-badge--warning">Severity {{.Incident.Severity}}</span></div><h2>{{.Incident.Title}}</h2><p>{{.Incident.Summary}}</p></div></div></section>
<div class="crab-dashboard-grid crab-section-gap">
  <section class="gas-panel"><h2>Scope &amp; impact</h2><div class="crab-record-list">{{range .Operations.Scopes}}<div class="crab-record"><strong>{{.Impact}}</strong><span class="gas-muted">{{.Confidence}} · {{.Maker}} · {{.RecordedAt}}</span>{{if .AffectedAssets}}<span>Assets: {{.AffectedAssets}}</span>{{end}}{{if .AffectedServices}}<span>Services: {{.AffectedServices}}</span>{{end}}{{if .PeopleDataPopulations}}<span>People/data: {{.PeopleDataPopulations}}</span>{{end}}{{if .Locations}}<span>Locations: {{.Locations}}</span>{{end}}{{if .Suppliers}}<span>Suppliers: {{.Suppliers}}</span>{{end}}<span>Reason/evidence: {{.ReasonEvidence}}</span></div>{{else}}<div class="gas-empty">No scope assessment yet.</div>{{end}}</div><hr><form method="post" action="/incident/{{.Incident.IncidentID}}/operations/scope" class="gas-form"><div class="gas-field"><label>Impact</label><textarea name="impact" required></textarea></div><div class="gas-field"><label>Confidence</label><input name="confidence" placeholder="high / medium / low" required></div><div class="gas-field"><label>Reason / evidence</label><textarea name="reason_evidence" required></textarea></div><div class="gas-field"><label>Affected assets</label><textarea name="affected_assets" placeholder="One per line"></textarea></div><div class="gas-field"><label>Affected services</label><textarea name="affected_services" placeholder="One per line"></textarea></div><div class="gas-field"><label>People / data populations</label><textarea name="people_data_populations" placeholder="One per line"></textarea></div><div class="gas-field"><label>Locations</label><textarea name="locations" placeholder="One per line"></textarea></div><div class="gas-field"><label>Suppliers</label><textarea name="suppliers" placeholder="One per line"></textarea></div><div><button class="gas-button gas-button--primary">Record scope assessment</button></div></form></section>
  <section class="gas-panel"><h2>Severity governance</h2>{{range .Operations.PendingSeverity}}<form method="post" action="/incident/{{$.Incident.IncidentID}}/operations/severity/decide" class="crab-approval"><input type="hidden" name="record_id" value="{{.RecordID}}"><input type="hidden" name="version" value="{{.Version}}"><div class="crab-approval__body"><strong>Proposed: {{.Severity}}</strong><span class="gas-muted">{{.Maker}} · {{.ProposedAt}}</span><span>{{.ReasonEvidence}}</span></div><div class="gas-cluster"><button class="gas-button gas-button--primary" name="outcome" value="confirmed">Confirm</button><button class="gas-button" name="outcome" value="rejected">Reject</button></div></form>{{else}}<div class="gas-empty">No severity change awaiting confirmation.</div>{{end}}<hr><form method="post" action="/incident/{{.Incident.IncidentID}}/operations/severity" class="gas-form"><div class="gas-field"><label>Proposed severity</label><input name="severity" required></div><div class="gas-field"><label>Reason / evidence</label><textarea name="reason_evidence" required></textarea></div><div><button class="gas-button gas-button--primary">Propose severity change</button></div></form><h3>Confirmed history</h3><div class="crab-record-list">{{range .Operations.SeverityHistory}}<div class="crab-record"><strong>{{.Severity}}</strong><span class="gas-muted">{{.Maker}} → {{.Confirmer}} · {{.RecordedAt}}</span><span>{{.ReasonEvidence}}</span></div>{{else}}<div class="gas-empty">No confirmed severity changes.</div>{{end}}</div></section>
  <section class="gas-panel"><h2>Shift handover</h2><div class="crab-record-list">{{range .Operations.Handovers}}<div class="crab-record"><strong>{{.Situation}}</strong><span class="gas-muted">{{.Maker}} · {{.RecordedAt}}</span>{{if .OperationalRoles}}<span>Roles: {{.OperationalRoles}}</span>{{end}}{{if .CriticalActions}}<span>Critical actions: {{.CriticalActions}}</span>{{end}}{{if .PendingDecisions}}<span>Pending decisions: {{.PendingDecisions}}</span>{{end}}{{if .Obligations}}<span>Obligations: {{.Obligations}}</span>{{end}}{{if .Unknowns}}<span>Unknowns: {{.Unknowns}}</span>{{end}}{{if .NextObjectives}}<span>Next objectives: {{.NextObjectives}}</span>{{end}}{{if .CommunicationCommitments}}<span>Communications: {{.CommunicationCommitments}}</span>{{end}}</div>{{else}}<div class="gas-empty">No handover generated.</div>{{end}}</div><hr><form method="post" action="/incident/{{.Incident.IncidentID}}/operations/handover" class="gas-form"><div class="gas-field"><label>Next objectives</label><textarea name="next_objectives" placeholder="One per line"></textarea></div><div class="gas-field"><label>Communication commitments</label><textarea name="communication_commitments" placeholder="One per line"></textarea></div><div><button class="gas-button gas-button--primary">Generate handover from current board</button></div></form></section>
</div>
<div class="crab-dashboard-grid crab-section-gap">
  <section class="gas-panel"><h2>Resource coordination</h2><div class="crab-record-list">{{range .Operations.Resources}}<div class="crab-record"><strong>{{.Request}}</strong><span class="gas-muted">{{.Category}} · {{.Priority}} · {{.Status}}</span><span>Owner: {{.OwnerHumanID}} · authority: {{.AuthoritySource}}</span>{{if .Notes}}<span>{{.Notes}}</span>{{end}}<form method="post" action="/incident/{{$.Incident.IncidentID}}/operations/resource" class="gas-form"><input type="hidden" name="record_id" value="{{.RecordID}}"><input type="hidden" name="category" value="{{.Category}}"><input type="hidden" name="request" value="{{.Request}}"><div class="gas-field"><label>Owner</label><input name="owner" value="{{.OwnerHumanID}}" required></div><div class="gas-field"><label>Priority</label><input name="priority" value="{{.Priority}}" required></div><div class="gas-field"><label>Status</label><input name="status" value="{{.Status}}" required></div><div class="gas-field"><label>Authority source</label><input name="authority_source" value="{{.AuthoritySource}}" required></div><div class="gas-field"><label>Notes</label><textarea name="notes">{{.Notes}}</textarea></div><div><button class="gas-button">Update request</button></div></form></div>{{else}}<div class="gas-empty">No resource requests.</div>{{end}}</div><h3>New request</h3><form method="post" action="/incident/{{.Incident.IncidentID}}/operations/resource" class="gas-form"><div class="gas-field"><label>Category</label><input name="category" required></div><div class="gas-field"><label>Request</label><textarea name="request" required></textarea></div><div class="gas-field"><label>Owner</label><input name="owner" required></div><div class="gas-field"><label>Priority</label><input name="priority" value="P1" required></div><div class="gas-field"><label>Status</label><input name="status" value="requested" required></div><div class="gas-field"><label>Authority source</label><input name="authority_source" required></div><div class="gas-field"><label>Notes</label><textarea name="notes"></textarea></div><div><button class="gas-button gas-button--primary">Record resource request</button></div></form></section>
  <section class="gas-panel"><h2>Known facts</h2><div class="crab-record-list">{{range .Incident.Facts}}<div class="crab-record"><strong>{{.Statement}}</strong><span class="gas-muted">{{.Source}}</span></div>{{else}}<div class="gas-empty">No facts recorded.</div>{{end}}</div></section>
  <section class="gas-panel"><h2>Live actions</h2><div class="crab-record-list">{{range .Incident.Actions}}<div class="crab-record"><strong>{{.Title}}</strong><span class="gas-muted">{{.Owner}} · {{.Status}} · {{.Priority}}</span></div>{{else}}<div class="gas-empty">No confirmed actions.</div>{{end}}</div><p><a href="/incident/{{.Incident.IncidentID}}">Open decision/timeline board</a></p></section>
</div>
{{end}}`))
